// Thin adapters between mermaid's `LayoutData` and the `layered` engine's own contract:
// `LayoutData` (after DOM measurement) → `LayoutGraph`, and `LayoutModel` → positions and
// axis-tagged routes on the `LayoutData` nodes and edges. Route ends come out of the engine on
// the node's bounding box; `clipRouteEnds` moves them onto the drawn shape with the shape's own
// `intersect`, along the flow only, so each end keeps the side and port the engine chose.
import type { Edge, LayoutData, Node } from '../../types.js';
import { withLineIntersectionOrigin } from '../../rendering-elements/intersect/intersection-query.js';
import { isAxisTaggedRoute } from '../../rendering-elements/routeGeometry.js';
import { layered, layoutSettings } from './index.js';
import type {
  Dir,
  EdgeRouting,
  LayoutEdge,
  LayoutGraph,
  LayoutGroup,
  LayoutModel,
  LayoutNode,
  RoutePoint,
} from './types.js';

// Room around an edge label, as v13 gives it (`LABEL_W`, `LABEL_H`).
const LABEL_W = 12;
const LABEL_H = 4;
// The room an arrowhead takes at an edge's head (v13 `HEAD_ROOM`).
const HEAD_ROOM = 7;

// Room between a subgraph's border and its content (v13 `GROUP_PAD`), and between its title
// and its content.
const GROUP_PAD = 20;
const TITLE_GAP = 12;

const DIRS: Record<string, Dir> = { TB: 'TB', TD: 'TB', BT: 'BT', LR: 'LR', RL: 'RL' };

function direction(data: LayoutData): Dir {
  return DIRS[String(data.direction ?? '').toUpperCase()] ?? 'TB';
}

const sideways = (dir: Dir): boolean => dir === 'LR' || dir === 'RL';

// How much of the side edges meet may be shared out between edge ends, for shapes that are
// narrower there than their box (v13 `shapeSpan`). Other shapes keep the engine's default.
type Span = (w: number, h: number, sideways: boolean) => number;
const roundSpan: Span = (w, h, s) => (s ? h : w) * 0.6;
const SPANS = new Map<string, Span>([
  ...[
    'circle',
    'circ',
    'doublecircle',
    'double-circle',
    'dbl-circ',
    'ellipse',
    'diamond',
    'diam',
    'decision',
    'question',
    'sm-circ',
    'small-circle',
    'start',
    'fr-circ',
    'framed-circle',
    'stop',
    'f-circ',
    'filled-circle',
    'junction',
    'cross-circ',
    'crossed-circle',
    'summary',
    // State diagram start, end and choice; mindmap cloud and bang.
    'stateStart',
    'stateEnd',
    'choice',
    'cloud',
    'bang',
  ].map((name) => [name, roundSpan] as const),
  ...['stadium', 'terminal', 'pill'].map(
    (name) => [name, ((w, h, s) => (s ? h * 0.6 : w - h)) as Span] as const
  ),
  ...['hexagon', 'hex', 'prepare'].map(
    (name) => [name, ((w, h, s) => (s ? h * 0.5 : w - h / 2 - 12)) as Span] as const
  ),
]);

const size = (value: unknown): number =>
  typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : 0;

type Routing = EdgeRouting | 'rounded';
const ROUTINGS = new Set<string>(['rounded', 'curved', 'stepped', 'straight']);

/** The `layered.edgeRouting` the diagram asks for; anything unknown uses rounded routes. */
function routing(data: LayoutData): Routing {
  const chosen = data.config?.layered?.edgeRouting;
  return chosen && ROUTINGS.has(chosen) ? chosen : 'rounded';
}

// Curves that already draw a stepped route as steps.
const STEPS = new Set(['step', 'stepBefore', 'stepAfter']);

/**
 * The curve an edge is drawn with, so each routing reads as its name: a stepped route as steps
 * (unless the edge already has a step curve), a rounded route as radius-5 arcs, and a straight
 * route as lines. Curved routing keeps the edge's own curve.
 */
function drawnCurve(mode: Routing, curve: Edge['curve']): Edge['curve'] {
  if (mode === 'rounded') {
    return 'rounded';
  }
  if (mode === 'straight') {
    return 'linear';
  }
  if (mode === 'stepped') {
    return curve && STEPS.has(curve) ? curve : 'step';
  }
  return curve;
}

// Mermaid draws a subgraph title at the top of its box, `subGraphTitleMargin.top` below the
// border, so the band above the content holds both margins, the title and a gap. The margin is
// read from the flowchart config for every diagram, as dagre does (`getSubGraphTitleMargins`).
function toLayoutGroup(n: Node, data: LayoutData, groupIds: Set<string>): LayoutGroup {
  const margin = data.config?.flowchart?.subGraphTitleMargin;
  const titleWidth = size(n.labelBBox?.width);
  const titleHeight = size(n.labelBBox?.height);
  const titled = titleWidth > 0 && titleHeight > 0;
  const group: LayoutGroup = {
    id: n.id,
    padding: {
      top: titled ? size(margin?.top) + size(margin?.bottom) + TITLE_GAP : GROUP_PAD,
      right: GROUP_PAD,
      bottom: GROUP_PAD,
      left: GROUP_PAD,
    },
  };
  if (n.parentId && groupIds.has(n.parentId)) {
    group.parent = n.parentId;
  }
  const dir = n.dir ? DIRS[String(n.dir).toUpperCase()] : undefined;
  if (dir) {
    group.direction = dir;
  }
  if (titled) {
    group.title = { width: titleWidth, height: titleHeight };
  }
  return group;
}

// A subgraph that sits inside one of its own descendants cannot be drawn as nested boxes. The
// flowchart grammar accepts such input, and the engine would lift the loop apart into a drawing
// that looks valid, so it is refused here, as dagre refuses it.
function checkNesting(groups: LayoutGroup[]): void {
  const parentOf = new Map(groups.map((g) => [g.id, g.parent]));
  for (const { id } of groups) {
    const seen = new Set<string>([id]);
    for (let p = parentOf.get(id); p !== undefined; p = parentOf.get(p)) {
      if (seen.has(p)) {
        throw new Error(`layered: subgraph '${p}' is nested inside itself`);
      }
      seen.add(p);
    }
  }
}

function hasLabel(edge: Edge): boolean {
  return typeof edge.label === 'string' ? edge.label.trim().length > 0 : Boolean(edge.label);
}

/** The engine's input for a measured `LayoutData`: nodes, subgraphs (as groups) and edges. */
export function toLayoutGraph(data: LayoutData): LayoutGraph {
  const dir = direction(data);
  // Spacing as dagre reads it: the renderer's own first, then the `flowchart` section (where
  // the ER renderer puts its spacing), then v12's defaults.
  const flowchart = data.config?.flowchart;
  const { spacing } = layoutSettings({
    nodeSpacing: size(data.nodeSpacing) || size(flowchart?.nodeSpacing) || undefined,
    rankSpacing: size(data.rankSpacing) || size(flowchart?.rankSpacing) || undefined,
  });
  const groupIds = new Set(data.nodes.filter((n) => n.isGroup).map((n) => n.id));
  const groups = data.nodes.filter((n) => n.isGroup).map((n) => toLayoutGroup(n, data, groupIds));
  checkNesting(groups);
  const nodes: LayoutNode[] = [];
  const ids = new Set<string>(groupIds);
  for (const n of data.nodes) {
    if (n.isGroup) {
      continue;
    }
    ids.add(n.id);
    const width = size(n.width);
    const height = size(n.height);
    const node: LayoutNode = { id: n.id, width, height };
    if (n.parentId && groupIds.has(n.parentId)) {
      node.parent = n.parentId;
    }
    const span = n.shape ? SPANS.get(n.shape) : undefined;
    if (span) {
      node.span = Math.max(0, span(width, height, sideways(dir)));
    }
    nodes.push(node);
  }
  const edges: LayoutEdge[] = [];
  for (const e of data.edges) {
    if (e.isLayoutOnly || !e.start || !e.end || !ids.has(e.start) || !ids.has(e.end)) {
      continue;
    }
    const edge: LayoutEdge = {
      id: e.id,
      source: e.start,
      target: e.end,
      minLen: Math.max(1, Math.round(size(e.minlen) || 1)),
    };
    const lw = size(e.width);
    if (hasLabel(e) && lw > 0) {
      edge.label = { width: lw + LABEL_W, height: size(e.height) + LABEL_H };
    }
    edges.push(edge);
  }
  // v13 hands the engine `diagramPadding` (v12 default 8); mermaid's renderers add that same
  // padding themselves when they set up the viewport, so the engine adds none.
  const mode = routing(data);
  return {
    direction: dir,
    nodes,
    edges,
    groups,
    spacing,
    diagramPadding: 0,
    // Rounded corners need the same right-angle tracks as stepped routes.
    routing: mode === 'rounded' ? 'stepped' : mode,
    headRoom: HEAD_ROOM,
  };
}

/** Writes the engine's positions, routes and label centres back onto `LayoutData`. */
export function applyLayoutModel(data: LayoutData, model: LayoutModel): void {
  const mode = routing(data);
  for (const n of data.nodes) {
    const placed = model.nodes.get(n.id);
    if (placed) {
      n.x = placed.x;
      n.y = placed.y;
      continue;
    }
    // Clusters are sized by the engine; `insertCluster` draws them centred on `x`, `y`.
    const cluster = n.isGroup ? model.groups.get(n.id) : undefined;
    if (cluster) {
      n.x = cluster.x;
      n.y = cluster.y;
      n.width = cluster.width;
      n.height = cluster.height;
    }
  }
  for (const e of data.edges) {
    const routed = model.edges.get(e.id);
    if (!routed) {
      continue;
    }
    e.points = routed.points.map((p) => ({ x: p.x, y: p.y, axis: p.axis }));
    e.curve = drawnCurve(mode, e.curve);
    if (routed.label) {
      e.x = routed.label.x;
      e.y = routed.label.y;
    }
  }
}

type Outline = Node & { intersect: NonNullable<Node['intersect']> };

const hasOutline = (n: Node | undefined): n is Outline =>
  n !== undefined &&
  !n.isGroup &&
  typeof n.intersect === 'function' &&
  Number.isFinite(n.x) &&
  Number.isFinite(n.y);

// Whether `p` lies inside the shape, asking the shape's own `intersect` where its outline is on
// the ray from the centre through `p`. Mermaid's shapes are all star-shaped about their centre.
function inside(n: Outline, p: { x: number; y: number }): boolean {
  const d = Math.hypot(p.x - n.x!, p.y - n.y!);
  if (d < 1e-6) {
    return true;
  }
  const o = n.intersect(p);
  const r = Math.hypot(o.x - n.x!, o.y - n.y!);
  return Number.isFinite(r) && d <= r + 1e-6;
}

// Moves a route end from the node's box onto its outline, square to the box side it sits on
// (as v13's `inset` does), so the end keeps its side and its place along that side.
function onOutline(n: Outline, end: RoutePoint): RoutePoint {
  const onTopOrBottom = Math.abs(Math.abs(end.y - n.y!) - size(n.height) / 2) < 0.5;
  const onLeftOrRight = Math.abs(Math.abs(end.x - n.x!) - size(n.width) / 2) < 0.5;
  if (!onTopOrBottom && !onLeftOrRight) {
    return end;
  }
  const met = firstMet(n, end, onTopOrBottom);
  if (met) {
    return met;
  }
  if (inside(n, end)) {
    return end;
  }
  // Towards the centre line, from the box side.
  const to = onTopOrBottom ? { x: end.x, y: n.y! } : { x: n.x!, y: end.y };
  if (!inside(n, to)) {
    // The port lies outside the shape altogether: meet the outline on the way to the centre.
    const o = n.intersect(end);
    return Number.isFinite(o.x) && Number.isFinite(o.y) ? { ...end, x: o.x, y: o.y } : end;
  }
  let outside = 0;
  let within = 1;
  for (let i = 0; i < 40; i++) {
    const t = (outside + within) / 2;
    const p = { x: end.x + (to.x - end.x) * t, y: end.y + (to.y - end.y) * t };
    if (inside(n, p)) {
      within = t;
    } else {
      outside = t;
    }
  }
  return {
    ...end,
    x: end.x + (to.x - end.x) * within,
    y: end.y + (to.y - end.y) * within,
  };
}

// Where the route, carried on along the flow from its end on the box side, first meets the
// outline (#8833). The shared `intersect.rect`, `intersect.ellipse` and `intersect.polygon`
// honour a line origin, so most built-in shapes answer this directly, which also holds for
// outlines that are not star-shaped, such as the lightning bolt's zigzag: there the bisection
// below settles on an inner kink, in the middle of the shape. A custom `intersect` that ignores
// the origin answers for the line from the centre instead, which does not lie on the route
// unless the end is on the centre line; then `undefined`, and the caller carries on.
function firstMet(n: Outline, end: RoutePoint, onTopOrBottom: boolean): RoutePoint | undefined {
  // The same point on the box's opposite side: the line through the two is the route's.
  const far = onTopOrBottom ? { x: end.x, y: 2 * n.y! - end.y } : { x: 2 * n.x! - end.x, y: end.y };
  const o = n.intersect(withLineIntersectionOrigin(end, far));
  if (!o || !Number.isFinite(o.x) || !Number.isFinite(o.y)) {
    return undefined;
  }
  // No crossing at all comes back as the node itself, its centre.
  if ((o as unknown) === n || (o.x === n.x && o.y === n.y)) {
    return undefined;
  }
  const onRoute = onTopOrBottom ? Math.abs(o.x - end.x) < 0.5 : Math.abs(o.y - end.y) < 0.5;
  const inBox =
    Math.abs(o.x - n.x!) <= size(n.width) / 2 + 0.5 &&
    Math.abs(o.y - n.y!) <= size(n.height) / 2 + 0.5;
  if (!onRoute || !inBox) {
    return undefined;
  }
  // Only moved along the flow, so the end keeps its place along the side exactly.
  return onTopOrBottom ? { ...end, y: o.y } : { ...end, x: o.x };
}

/**
 * Moves each axis-tagged route's ends from the bounding box onto the shape outline, using the
 * `intersect` the shape installed when it was drawn. Nodes without one (headless runs) keep the
 * box ends.
 */
export function clipRouteEnds(data: LayoutData): void {
  const byId = new Map(data.nodes.map((n) => [n.id, n]));
  for (const e of data.edges) {
    const points = e.points;
    if (!isAxisTaggedRoute(points)) {
      continue;
    }
    const src = byId.get(e.start ?? '');
    const dst = byId.get(e.end ?? '');
    const next = [...points];
    if (hasOutline(src)) {
      next[0] = onOutline(src, next[0]);
    }
    if (hasOutline(dst)) {
      next[next.length - 1] = onOutline(dst, next[next.length - 1]);
    }
    e.points = next;
  }
}

/**
 * The layout core shared by the browser renderer and headless tests: translate, run the
 * engine, write back, and put route ends on the shapes.
 */
export function runLayeredLayoutCore(data: LayoutData): LayoutModel {
  const model = layered(toLayoutGraph(data));
  applyLayoutModel(data, model);
  clipRouteEnds(data);
  return model;
}
